from subprocess import PIPE, Popen

from taf.converters.eventdecoder.interface import eventdecoder
from taf.rfrl.procedures.resources.python.sw_update.SW_update import SW_update
from taf.rfrl.procedures.resources.python.tti_decoder.exceptions import (
    TtiDecPackageInstallationError,
)
from taf.rfrl.procedures.resources.python.logger import (
    log_input_and_output,
    log_result,
    log_operation,
    log_warning,
)


class TTI_decoder:
    def __init__(self):
        self._tti_converter = eventdecoder()
        self._tti_decoding_sw_version = None

    @log_input_and_output
    def convert_tti_pcap(self, tti_file_path, output_file_path, output_file_format, conversion_filter, sw_version):
        """
         Converts TTI pcap file to CSV or json format file.

        :param tti_file_path: absolute path to TTI pcap file (with pcap extension),
                              e.g.: /home/ute/tcpdump/tcpdump.pcap
        :type tti_file_path: str
        :param output_file_path: absolute path to converted output file (without file extension),
                                 e.g.: /home/ute/tcpdump/output_file
        :type output_file_path: str
        :param output_file_format: format of output file, one of following: legacyCsv, excelCsv or json
        :type output_file_format: str
        :param conversion_filter: Required only for json or excelCsv format. TTI events phrases to be used as filters
                                  during pcap conversion, e.g.: dlFdSchedData|dlFlowControlData|utcTimestampData
        :type conversion_filter: dict or str
        :param sw_version: SW version for TTI decoding package. Should starts with "SBTS00" header in case of SBTS
                           trunk stream, e.g.: SBTS00_ENB_9999_240806_000003
        :type sw_version: str
        """
        if sw_version != self._tti_decoding_sw_version:
            log_operation(f"Downloading TTI decoding package for sw version {sw_version}...")
            tti_decoding_package_path = self._download_tti_decoding_package(sw_version=sw_version)

            if self._is_installation_required(tti_decoding_package_path=tti_decoding_package_path):
                log_operation(f"Installing TTI decoding package ({tti_decoding_package_path})...")
                self._install_tti_decoding_package(tti_decoding_package_path=tti_decoding_package_path)
            else:
                log_result("TTI decoding package installation is not required")

            self._tti_decoding_sw_version = sw_version

        converter_name = self._create_tti_converter(tti_file_path, output_file_path, output_file_format,
                                                    conversion_filter)

        self._tti_converter.convert(name=converter_name)

    @log_input_and_output
    def _create_tti_converter(self, tti_file_path, output_file_path, output_file_format, conversion_filter):
        """
         Creates TTI pcap converter with 'ttitrace_converter' name.

        :param tti_file_path: absolute path to TTI pcap file (with pcap extension),
                              e.g.: /home/ute/tcpdump/tcpdump.pcap
        :type tti_file_path: str
        :param output_file_path: absolute path to converted output file (without file extension),
                                 e.g.: /home/ute/tcpdump/output_file
        :type output_file_path: str
        :param output_file_format: format of output file, one of following: legacyCsv, excelCsv or json
        :type output_file_format: str
        :param conversion_filter: Required only for json or excelCsv format. TTI events phrases to be used as filters
                                  during pcap conversion, e.g.: dlFdSchedData|dlFlowControlData|utcTimestampData
        :type conversion_filter: dict or str

        :return converter name as 'ttitrace_converter'
        :rtype str
        """
        converter_name = "ttitrace_converter"
        self._tti_converter.create_eventdecoder_converter(name=converter_name,
                                                          input_file_path=tti_file_path,
                                                          output_file_format=output_file_format,
                                                          output_file_path=output_file_path,
                                                          conversion_filter=conversion_filter)
        return converter_name

    @log_input_and_output
    def _download_tti_decoding_package(self, sw_version, download_path="/tmp"):
        """
        Downloads TTI decoding package for particular SW vefvrsion.

        :param sw_version: SW version for TTI decoding package, i.e. SBTS00_ENB_9999_240806_000003
        :type sw_version: str
        :param download_path: path where TTI decoding package will be saved, defaults to '/tmp'
        :type download_path: str

        :return full path to downloaded TTI decoding package i.e. "/tmp/SBTS00_ENB_9999_240806_000003_tti-dec.deb"
        :rtype str
        """
        sw = SW_update()
        return sw.download_gnb_tti_decoding_package(path=download_path,
                                                    sw_version=sw_version)

    @log_input_and_output
    def _install_tti_decoding_package(self, tti_decoding_package_path):
        """
        Installs TTI decoding package using "sudo dpkg -i <tti_decoding_package_path>" system command.

        :param tti_decoding_package_path: full path to downloaded TTI decoding package i.e.
                                     "/tmp/SBTS00_ENB_9999_240806_000003_tti-dec.deb"
        :type tti_decoding_package_path: str

        :raises TtiDecPackageInstallationError: when TTI decoding package installation failed.
        """
        subproc = Popen(f"sudo dpkg -i {tti_decoding_package_path}", shell=True, stdout=PIPE, stderr=PIPE)
        stdout, stderr = subproc.communicate()

        if stderr:
            raise TtiDecPackageInstallationError(f"TTI Decoding Package installation ERROR: {stderr.decode('utf-8')}")

        log_result(f"Installation result: {stdout.decode('utf-8')}")

    @log_input_and_output
    def _is_installation_required(self, tti_decoding_package_path):
        """
        Checks if TTI decoding package installation is required based on current installed package version.

        :param tti_decoding_package_path: full path to TTI decoding package to install, i.e.
                                     "/tmp/SBTS00_ENB_9999_240806_000003_tti-dec.deb"
        :type tti_decoding_package_path: str

        :return True if TTI decoding package installation is required, False otherwise
        :rtype bool
        """
        subproc = Popen("sudo dpkg -s tti-dec | grep '^Version:'", shell=True, stdout=PIPE, stderr=PIPE)
        stdout, stderr = subproc.communicate()

        if stderr:
            current_version_output = stderr.decode('utf-8')
        else:
            current_version_output = stdout.decode('utf-8')

        if "Version: " not in current_version_output:
            log_result(f"Not possible to get package version from output: '{current_version_output}'")
            return True
        else:
            current_tti_decoding_version = str(current_version_output.split("Version: ")[-1])

        tti_decoding_package_version = self._get_tti_decoding_package_version(
            tti_decoding_package_path=tti_decoding_package_path)

        return current_tti_decoding_version != tti_decoding_package_version

    @log_input_and_output
    def _get_tti_decoding_package_version(self, tti_decoding_package_path):
        """
        Gets version of particular TTI decoding package, using "sudo dpkg-deb -f <tti_decoding_package_path> Version"
        system command.

        :param tti_decoding_package_path: full path to TTI decoding package i.e.
                                     "/tmp/SBTS00_ENB_9999_240806_000003_tti-dec.deb"
        :type tti_decoding_package_path: str

        :return version of TTI decoding package or empty string in case of any exception during system command
                execution.
        :rtype str
        """
        subproc = Popen(f"sudo dpkg-deb -f {tti_decoding_package_path} Version", shell=True, stdout=PIPE, stderr=PIPE)
        stdout, stderr = subproc.communicate()

        if stderr:
            log_warning(f"ERROR during command execution to get dpkg-deb package version: '{stderr.decode('utf-8')}'")
            return ''

        return stdout.decode('utf-8')
